pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzing: from address and an array of target addresses and a uint value
    // The fuzzer will supply arbitrary addresses and array contents (EOAs). Calls to EOAs will succeed (no revert).
    function testFuzz_property(address from, address[] memory tos, uint256 v) public {
        // require the admissible domain: tos must be non-empty to avoid revert in both versions
        vm.assume(tos.length > 0);

        // Call transfer and observe whether it returns true (no revert expected)
        bool ok;
        try c.transfer(from, address(0x12345), tos, v) returns (bool ret) {
            ok = ret; // capture the return value
        } catch {
            ok = false; // if it reverts, treat as false (but with tos.length>0 and EOAs as tos, should not revert)
        }

        // The universal property: the reference implementation always returns true for any non-reverting call.
        // So assertTrue on the observed return value. This will pass on the reference C and fail on the mutant
        // for inputs where the call completes but returns false.
        assertTrue(ok);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed params: from address, array length seed, value v
    // We cannot fuzz raw address for the callee behavior, so we deploy a helper that fails on-demand.
    function testFuzz_property(address from, uint16 seed, uint256 v) public {
        // Keep seed in a reasonable range for array size
        uint256 len = uint256(seed) % 8 + 1; // length in [1,8]

        // Build an array of 'tos' addresses where some entries point to a helper that will fail
        address[] memory tos = new address[](len);

        // Deploy two helpers: one that will succeed (returns true on fallback) and one that will fail (revert)
        ResponderGood good = new ResponderGood();
        ResponderBad bad = new ResponderBad();

        // Populate tos with a pattern depending on seed bits so fuzzer can explore combos
        for (uint i = 0; i < len; i++) {
            // use bits of seed to choose good or bad
            if (((uint256(seed) >> i) & 1) == 1) {
                tos[i] = address(bad);
            } else {
                tos[i] = address(good);
            }
        }

        // We must call c.transfer with caddress set to the callee we want invoked (the contract under test calls caddress.call(..., from, tos[i], v))
        // The reference contract will ignore return values and ultimately return true if it doesn't revert.
        // The mutant will short-circuit and return false if any call returns false (i.e., the call did not revert but returned ok==false).
        // Our ResponderBad will simulate a low-level call that returns (false, "") by not reverting but using assembly to return zero-sized data and indicate failure.
        // However, a low-level call's 'ok' is false only if the callee reverts or the call runs out of gas or execution uses invalid opcode; to simulate a call that returns ok==false without revert is not possible from the callee — instead, the mutant checks the boolean 'ok' returned by call; call returns false iff the callee reverted or failed. Therefore we implement ResponderBad to revert, and ResponderGood to succeed.

        // Choose the caddress to be a wrapper that forwards to the target 'tos' addresses: we need caddress.call(selector, from, tos[i], v) to invoke the target contract's transferFrom(from,tos[i],v).
        // Create a Forwarder that, when called with transferFrom selector, will call the target 'tos' address passed as the second arg to the selector payload. To simplify, we will instead make caddress equal to an Adaptor that ignores the payload's target and simply calls the target address provided as the second argument using low-level call decoding.

        // Deploy Adaptor that will decode parameters and call the target address (the second parameter in the encoded calldata) using call:
        Adaptor adaptor = new Adaptor();

        // Now perform the call to c.transfer; we fuzz 'from' and 'v' already.
        bool ok;
        try c.transfer(from, address(adaptor), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property we assert: the reference implementation (which ignores individual call failures and only reverts if something reverts) will never revert here, because adaptor and helpers do not revert the top-level call chain in all arrangements where at least one callee succeeds; specifically, if at least one of the tos is a successful responder, the reference returns true (call does not revert). We must assert that c.transfer does not revert for this constructed scenario when at least one good exists.
        // Ensure there is at least one good responder in the array so the reference should succeed for all such inputs.
        bool hasGood = false;
        for (uint i = 0; i < len; i++) {
            if (tos[i] == address(good)) { hasGood = true; break; }
        }

        // Only assert the property in the admissible domain: at least one good callee present.
        vm.assume(hasGood);

        // The reference contract's behavior: it should not revert and should return true. We observe this by checking ok==true.
        // This assertion will hold for the reference C for all such inputs, but the mutant (which short-circuits on any failing call) can return false (and thus the try would succeed but return value false if caught differently). Because try/catch on external call only distinguishes revert vs non-revert, to also capture a differing returned boolean we rely on that the reference returns true (no revert) and mutant may return false (also no revert) — but try/catch can't see the returned bool. However the problem statement allows asserting over the public return value; thus we instead call as low-level and capture return value by declaring an interface and reading returned bool.
        // To read the returned bool from c.transfer, we must call it directly (not via try) and capture the returned value. Use a local interface to capture the returned bool.

        bool ret = C(address(c)).transfer(from, address(adaptor), tos, v);

        // Exactly one assertion: the reference contract should always return true for our inputs where at least one callee succeeds.
        assertTrue(ret);
    }
}

// Adaptor: decodes the incoming calldata for transferFrom(selector, from, to, v) and forwards to the 'to' address provided in the calldata
contract Adaptor {
    // The adaptor expects calldata of the form: selector(transferFrom) + abi.encode(from, to, v)
    // But the contract C calls caddress.call(abi.encodeWithSelector(id,from,_tos[i],v)); where _tos[i] is the 'to' address.
    // So adaptor will decode (address from, address to, uint256 v) from calldata[4:]
    fallback() external payable returns (bytes memory) {
        // calldata layout: 4 bytes selector | abi encoded (address,address,uint256)
        // We decode the params and call the 'to' address's transferFrom(from,to,v) via low-level call.
        bytes memory data = msg.data;
        require(data.length >= 4 + 32*3, "bad");
        // skip selector
        // read from, to, v
        address from;
        address to;
        uint256 v;
        assembly {
            // skip 4 bytes selector, then the ABI encoding starts
            let ptr := add(data, 36) // data pointer + 4 + 32 (data header offset)
            from := mload(ptr)
            to := mload(add(ptr,32))
            v := mload(add(ptr,64))
        }
        // Now invoke transferFrom(from,to,v) on the 'to' contract
        bytes4 sel = bytes4(keccak256("transferFrom(address,address,uint256)"));
        // Forward the call to the target 'to' address
        (bool ok, bytes memory ret) = to.call(abi.encodeWithSelector(sel, from, to, v));
        if (!ok) {
            // bubble up revert so mutant's behavior (which checks ok) sees failure; for reference implementation we want some calls to revert and some succeed without reverting the outer transfer
            // Return low-level failure to caller
            assembly { revert(add(ret,32), mload(ret)) }
        }
        return ret;
    }
}

// A responder that always succeeds (does not revert) for transferFrom
contract ResponderGood {
    event Called(address from, address to, uint256 v);
    fallback() external payable returns (bytes memory) {
        // decode args to emit event
        address from;
        address to;
        uint256 v;
        assembly {
            // skip selector
            let ptr := add(calldataload(0x40), 0)
        }
        // Safely decode via abi.decode using a small try-catch wrapper
        // We keep it simple: do not revert and return empty bytes
        emit Called(address(0), address(0), 0);
        return abi.encode(true);
    }
}

// A responder that always reverts for transferFrom
contract ResponderBad {
    fallback() external payable {
        revert("bad");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: a nonzero uint decides value, an address decides which helper to include in the list
    // We need at least one parameter; include uint256 v and address goodAddr and address badAddr and uint256 len
    // The fuzzer will search these to find scenarios; we will deploy helpers and construct an _tos array mixing them.
    function testFuzz_property(uint256 v, address goodSeed, address badSeed, uint256 len) public {
        // keep len in a reasonable but wide bound and require non-empty _tos as the contract requires
        uint256 n = bound(len, 1, 4);

        // Deploy two helpers: one that succeeds on calls (returns true) and one that returns false (does not revert but returns false)
        // We cannot make an EOA behave differently so deploy explicit contracts.
        GoodC good = new GoodC();
        BadC bad = new BadC();

        // Build an array _tos mixing good and bad addresses; include at least one good and one bad when possible
        address[] memory tos = new address[](n);
        // Use the provided seeds to choose positions so the fuzzer controls layout
        uint256 gpos = uint256(uint160(goodSeed)) % n;
        uint256 bpos = uint256(uint160(badSeed)) % n;
        // ensure positions possibly differ; if they collide and n>1, move bpos
        if (gpos == bpos && n > 1) {
            bpos = (bpos + 1) % n;
        }
        for (uint256 i = 0; i < n; i++) {
            if (i == gpos) tos[i] = address(good);
            else if (i == bpos) tos[i] = address(bad);
            else tos[i] = address(good);
        }

        // Now call through C.transfer. The reference ignores the boolean return of low-level call, only reverts if callee reverts.
        // Our helpers are designed so that GoodC.call returns true (i.e., does not revert and returns true-ish),
        // and BadC.call returns false (it returns false via low-level return data, but does NOT revert).
        // According to the reference C, since none of the callees revert, transfer should return true for all inputs.
        bool ok;
        try c.transfer(address(this), address(this), tos, v) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false;
        }

        // The universal property: for any admissible inputs (n>=1, any v and seeds), the reference implementation returns true
        // because it ignores call return values and none of our helpers revert. The mutant that checks call's bool and
        // short-circuits on false would return false when it encounters BadC in the loop. We assert that c.transfer returned true.
        assertTrue(ok);
    }
}

// Helper that does not revert and returns true from the selector transferFrom(address,address,uint256)
contract GoodC {
    // emulate ERC20-like transferFrom selector: transferFrom(address,address,uint256)
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
    // fallback to accept any selector and return true-encoded
    fallback() external pure returns (bytes memory) {
        // return encoded true
        bytes memory b = abi.encode(true);
        return b;
    }
}

// Helper that does not revert but returns false (i.e., low-level call returns ok=false to caller?)
// Note: low-level call's ok=false happens only on revert; to simulate a callee that returns false in returndata
// we implement transferFrom that returns false (which results in call success but return data = false). The mutant
// checks the low-level boolean 'ok' which would still be true. To trigger the mutant's behavior (it checks ok from call),
// we instead implement a helper that uses the fallback to return no data but then the low-level call still succeeds.
// However, to ensure the mutant can distinguish, we implement a helper whose fallback uses 'return ""' producing empty data.
contract BadC {
    // return false value from selector
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return false;
    }
    fallback() external pure returns (bytes memory) {
        // return encoded false
        return abi.encode(false);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: one address that will be the failing callee index selector and a non-empty length
    function testFuzz_property(uint8 badIndex, uint256 len) public {
        // domain: len must be at least 1 and not absurdly large
        vm.assume(len > 0 && len <= 10);
        // badIndex chooses which position in the tos array will be the failing callee (wrap into range)
        uint256 idx = uint256(badIndex) % len;

        // deploy helper callees: a good callee that returns true (via non-reverting fallback)
        GoodCallee good = new GoodCallee();
        // a callee that performs a low-level return false (i.e., does NOT revert but returns empty/ok=false when called via low-level call)
        // We simulate a callee that returns no data but does not revert; low-level call to such contract yields ok=true.
        // To produce ok==false without revert, we implement a contract that deliberately uses selfdestruct to make subsequent calls fail
        // But selfdestruct would cause revert on call; instead we create a contract that returns a short bytes payload but the caller's call will still be ok==true.
        // The mutant's distinction is based on the low-level call returning false — which occurs when the callee uses revert? No: revert makes ok==false.
        // So we deploy a Reverter callee that always reverts (causing call to return ok==false). That matches the adversarial behavior needed.
        Reverter bad = new Reverter();

        // build tos array mixing goods and one bad at position idx
        address[] memory tos = new address[](len);
        for (uint i = 0; i < len; i++) {
            if (i == idx) tos[i] = address(bad);
            else tos[i] = address(good);
        }

        // call transfer and capture whether it returned or reverted; reference C returns true for any non-empty tos
        bool ok;
        try c.transfer(address(this), address(this), tos, 1) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false; // should not revert on non-empty tos for reference
        }

        // The universal property: reference contract always returns true for any non-empty tos (it ignores call return values)
        // So assertTrue on ok. This will pass on reference, and fail on the mutant for some fuzzed inputs (where a callee reverts causing mutant to return false).
        assertTrue(ok);
    }
}

contract GoodCallee {
    // accept any call and do nothing (succeeds)
    fallback() external payable {}
}

contract Reverter {
    // always revert so low-level calls return ok == false
    fallback() external payable {
        revert("fail");
    }
}
